class Solution {
    private java.util.Map<String, Integer> evalMap;
    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
        evalMap = new java.util.HashMap<>();
        for (int i = 0; i < evalvars.length; i++) evalMap.put(evalvars[i], evalints[i]);
        expression = expression.replace("(", "( ").replace(")", " )");
        java.util.Map<String, Integer> poly = parseExpr(expression.trim().split("\\s+"), new int[]{0});
        List<String> result = new java.util.ArrayList<>();
        List<String> keys = new java.util.ArrayList<>(poly.keySet());
        keys.sort((a, b) -> { int ca = a.isEmpty() ? 0 : a.split("\\*").length; int cb = b.isEmpty() ? 0 : b.split("\\*").length; return ca != cb ? cb - ca : a.compareTo(b); });
        for (String key : keys) { int c = poly.get(key); if (c != 0) result.add(key.isEmpty() ? "" + c : c + "*" + key); }
        return result;
    }
    private java.util.Map<String, Integer> parseExpr(String[] tokens, int[] idx) {
        java.util.Map<String, Integer> result = parseMulExpr(tokens, idx);
        while (idx[0] < tokens.length && (tokens[idx[0]].equals("+") || tokens[idx[0]].equals("-"))) {
            String op = tokens[idx[0]++];
            java.util.Map<String, Integer> right = parseMulExpr(tokens, idx);
            result = combine(result, right, op);
        }
        return result;
    }
    private java.util.Map<String, Integer> parseMulExpr(String[] tokens, int[] idx) {
        java.util.Map<String, Integer> result = parseAtom(tokens, idx);
        while (idx[0] < tokens.length && tokens[idx[0]].equals("*")) {
            idx[0]++;
            java.util.Map<String, Integer> right = parseAtom(tokens, idx);
            result = multiply(result, right);
        }
        return result;
    }
    private java.util.Map<String, Integer> parseAtom(String[] tokens, int[] idx) {
        if (tokens[idx[0]].equals("(")) { idx[0]++; java.util.Map<String, Integer> r = parseExpr(tokens, idx); idx[0]++; return r; }
        String token = tokens[idx[0]++];
        java.util.Map<String, Integer> r = new java.util.LinkedHashMap<>();
        if (evalMap.containsKey(token)) r.put("", evalMap.get(token));
        else if (Character.isDigit(token.charAt(0))) r.put("", Integer.parseInt(token));
        else r.put(token, 1);
        return r;
    }
    private java.util.Map<String, Integer> combine(java.util.Map<String, Integer> a, java.util.Map<String, Integer> b, String op) {
        java.util.Map<String, Integer> r = new java.util.LinkedHashMap<>(a);
        for (java.util.Map.Entry<String, Integer> e : b.entrySet()) r.merge(e.getKey(), op.equals("+") ? e.getValue() : -e.getValue(), Integer::sum);
        return r;
    }
    private java.util.Map<String, Integer> multiply(java.util.Map<String, Integer> a, java.util.Map<String, Integer> b) {
        java.util.Map<String, Integer> r = new java.util.LinkedHashMap<>();
        for (java.util.Map.Entry<String, Integer> e1 : a.entrySet()) for (java.util.Map.Entry<String, Integer> e2 : b.entrySet()) {
            List<String> vars = new java.util.ArrayList<>();
            if (!e1.getKey().isEmpty()) vars.addAll(java.util.Arrays.asList(e1.getKey().split("\\*")));
            if (!e2.getKey().isEmpty()) vars.addAll(java.util.Arrays.asList(e2.getKey().split("\\*")));
            java.util.Collections.sort(vars);
            String key = String.join("*", vars);
            r.merge(key, e1.getValue() * e2.getValue(), Integer::sum);
        }
        return r;
    }
}

