class Solution {
    private String[] tokens;
    private int index;
    private Map<String, Integer> values;

    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
        values = new HashMap<>();
        for (int i = 0; i < evalvars.length; i++) {
            values.put(evalvars[i], evalints[i]);
        }

        tokens = expression.replace("(", "( ").replace(")", " )").trim().split("\\s+");
        index = 0;
        TreeMap<List<String>, Integer> polynomial = parseExpression();

        List<List<String>> terms = new ArrayList<>(polynomial.keySet());
        terms.sort((a, b) -> {
            if (a.size() != b.size()) {
                return b.size() - a.size();
            }
            return compareTerm(a, b);
        });

        List<String> output = new ArrayList<>();
        for (List<String> term : terms) {
            int coefficient = polynomial.get(term);
            if (coefficient == 0) {
                continue;
            }
            if (term.isEmpty()) {
                output.add(String.valueOf(coefficient));
            } else {
                StringBuilder formatted = new StringBuilder(String.valueOf(coefficient));
                for (String variable : term) {
                    formatted.append('*').append(variable);
                }
                output.add(formatted.toString());
            }
        }
        return output;
    }

    private TreeMap<List<String>, Integer> parseExpression() {
        TreeMap<List<String>, Integer> result = parseTerm();
        while (index < tokens.length && !tokens[index].equals(")")) {
            String operator = tokens[index++];
            TreeMap<List<String>, Integer> right = parseTerm();
            result = add(result, right, operator.equals("+") ? 1 : -1);
        }
        return result;
    }

    private TreeMap<List<String>, Integer> parseTerm() {
        TreeMap<List<String>, Integer> result = parseFactor();
        while (index < tokens.length && tokens[index].equals("*")) {
            index++;
            result = multiply(result, parseFactor());
        }
        return result;
    }

    private TreeMap<List<String>, Integer> parseFactor() {
        String token = tokens[index];
        if (token.equals("(")) {
            index++;
            TreeMap<List<String>, Integer> inside = parseExpression();
            index++;
            return inside;
        }

        index++;
        if (Character.isDigit(token.charAt(0))) {
            return constant(Integer.parseInt(token));
        }
        if (values.containsKey(token)) {
            return constant(values.get(token));
        }

        TreeMap<List<String>, Integer> result = newPolynomial();
        result.put(List.of(token), 1);
        return result;
    }

    private TreeMap<List<String>, Integer> constant(int value) {
        TreeMap<List<String>, Integer> result = newPolynomial();
        if (value != 0) {
            result.put(List.of(), value);
        }
        return result;
    }

    private TreeMap<List<String>, Integer> add(TreeMap<List<String>, Integer> left,
                                               TreeMap<List<String>, Integer> right,
                                               int sign) {
        TreeMap<List<String>, Integer> result = newPolynomial();
        result.putAll(left);
        for (Map.Entry<List<String>, Integer> entry : right.entrySet()) {
            List<String> key = entry.getKey();
            int value = result.getOrDefault(key, 0) + sign * entry.getValue();
            if (value == 0) {
                result.remove(key);
            } else {
                result.put(key, value);
            }
        }
        return result;
    }

    private TreeMap<List<String>, Integer> multiply(TreeMap<List<String>, Integer> left,
                                                    TreeMap<List<String>, Integer> right) {
        TreeMap<List<String>, Integer> result = newPolynomial();
        for (Map.Entry<List<String>, Integer> a : left.entrySet()) {
            for (Map.Entry<List<String>, Integer> b : right.entrySet()) {
                List<String> variables = new ArrayList<>(a.getKey());
                variables.addAll(b.getKey());
                Collections.sort(variables);
                List<String> key = List.copyOf(variables);
                int value = result.getOrDefault(key, 0) + a.getValue() * b.getValue();
                if (value == 0) {
                    result.remove(key);
                } else {
                    result.put(key, value);
                }
            }
        }
        return result;
    }

    private TreeMap<List<String>, Integer> newPolynomial() {
        return new TreeMap<>(this::compareTerm);
    }

    private int compareTerm(List<String> a, List<String> b) {
        int limit = Math.min(a.size(), b.size());
        for (int i = 0; i < limit; i++) {
            int cmp = a.get(i).compareTo(b.get(i));
            if (cmp != 0) {
                return cmp;
            }
        }
        return Integer.compare(a.size(), b.size());
    }
}

