class Solution {
    private Map<String, Integer> values;

    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
        values = new HashMap<>();
        for (int i = 0; i < evalvars.length; i++) {
            values.put(evalvars[i], evalints[i]);
        }

        List<String> tokens = tokenize(expression);
        List<String> rpn = toReversePolish(tokens);
        Deque<Polynomial> stack = new ArrayDeque<>();
        for (String token : rpn) {
            if (isOperator(token)) {
                Polynomial right = stack.pop();
                Polynomial left = stack.pop();
                if (token.equals("*")) {
                    stack.push(left.multiply(right));
                } else {
                    stack.push(left.add(right, token.equals("+") ? 1 : -1));
                }
            } else {
                stack.push(atom(token));
            }
        }
        return stack.pop().format();
    }

    private List<String> tokenize(String expression) {
        String spaced = expression.replace("(", "( ").replace(")", " )");
        return Arrays.asList(spaced.trim().split("\s+"));
    }

    private List<String> toReversePolish(List<String> tokens) {
        List<String> output = new ArrayList<>();
        Deque<String> operators = new ArrayDeque<>();
        for (String token : tokens) {
            if (token.equals("(")) {
                operators.push(token);
            } else if (token.equals(")")) {
                while (!operators.peek().equals("(")) {
                    output.add(operators.pop());
                }
                operators.pop();
            } else if (isOperator(token)) {
                while (!operators.isEmpty()
                        && !operators.peek().equals("(")
                        && precedence(operators.peek()) >= precedence(token)) {
                    output.add(operators.pop());
                }
                operators.push(token);
            } else {
                output.add(token);
            }
        }
        while (!operators.isEmpty()) {
            output.add(operators.pop());
        }
        return output;
    }

    private Polynomial atom(String token) {
        if (values.containsKey(token)) {
            return Polynomial.constant(values.get(token));
        }
        if (Character.isDigit(token.charAt(0))) {
            return Polynomial.constant(Integer.parseInt(token));
        }
        return Polynomial.variable(token);
    }

    private boolean isOperator(String token) {
        return token.equals("+") || token.equals("-") || token.equals("*");
    }

    private int precedence(String token) {
        return token.equals("*") ? 2 : 1;
    }

    private static final class Polynomial {
        private final Map<List<String>, Integer> terms = new HashMap<>();

        static Polynomial constant(int value) {
            Polynomial polynomial = new Polynomial();
            if (value != 0) {
                polynomial.terms.put(List.of(), value);
            }
            return polynomial;
        }

        static Polynomial variable(String variable) {
            Polynomial polynomial = new Polynomial();
            polynomial.terms.put(List.of(variable), 1);
            return polynomial;
        }

        Polynomial add(Polynomial other, int sign) {
            Polynomial result = new Polynomial();
            result.terms.putAll(terms);
            for (Map.Entry<List<String>, Integer> entry : other.terms.entrySet()) {
                int next = result.terms.getOrDefault(entry.getKey(), 0) + sign * entry.getValue();
                if (next == 0) {
                    result.terms.remove(entry.getKey());
                } else {
                    result.terms.put(entry.getKey(), next);
                }
            }
            return result;
        }

        Polynomial multiply(Polynomial other) {
            Polynomial result = new Polynomial();
            for (Map.Entry<List<String>, Integer> left : terms.entrySet()) {
                for (Map.Entry<List<String>, Integer> right : other.terms.entrySet()) {
                    List<String> variables = new ArrayList<>(left.getKey());
                    variables.addAll(right.getKey());
                    Collections.sort(variables);
                    List<String> key = List.copyOf(variables);
                    int value = result.terms.getOrDefault(key, 0) + left.getValue() * right.getValue();
                    if (value == 0) {
                        result.terms.remove(key);
                    } else {
                        result.terms.put(key, value);
                    }
                }
            }
            return result;
        }

        List<String> format() {
            List<List<String>> keys = new ArrayList<>(terms.keySet());
            keys.sort((a, b) -> {
                if (a.size() != b.size()) {
                    return b.size() - a.size();
                }
                for (int i = 0; i < a.size(); i++) {
                    int cmp = a.get(i).compareTo(b.get(i));
                    if (cmp != 0) {
                        return cmp;
                    }
                }
                return 0;
            });

            List<String> answer = new ArrayList<>();
            for (List<String> key : keys) {
                int coefficient = terms.get(key);
                if (coefficient == 0) {
                    continue;
                }
                if (key.isEmpty()) {
                    answer.add(String.valueOf(coefficient));
                } else {
                    answer.add(coefficient + "*" + String.join("*", key));
                }
            }
            return answer;
        }
    }
}

import java.util.*;

class Solution {
    private String[] tokens;
    private int index;
    private Map<String, Integer> substitutions;

    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
        substitutions = new HashMap<>();
        for (int i = 0; i < evalvars.length; i++) {
            substitutions.put(evalvars[i], evalints[i]);
        }
        tokens = expression.replace("(", "( ").replace(")", " )").trim().split("\s+");
        index = 0;
        Poly answer = parseWithMinPrecedence(0);
        return answer.toList();
    }

    private Poly parseWithMinPrecedence(int minimumPrecedence) {
        Poly left = parsePrimary();
        while (index < tokens.length && isOperator(tokens[index])
                && precedence(tokens[index]) >= minimumPrecedence) {
            String operator = tokens[index++];
            Poly right = parseWithMinPrecedence(precedence(operator) + 1);
            if (operator.equals("*")) {
                left = left.times(right);
            } else {
                left = left.plus(right, operator.equals("+") ? 1 : -1);
            }
        }
        return left;
    }

    private Poly parsePrimary() {
        String token = tokens[index++];
        if (token.equals("(")) {
            Poly inside = parseWithMinPrecedence(0);
            index++;
            return inside;
        }
        if (substitutions.containsKey(token)) {
            return Poly.constant(substitutions.get(token));
        }
        if (Character.isDigit(token.charAt(0))) {
            return Poly.constant(Integer.parseInt(token));
        }
        return Poly.variable(token);
    }

    private boolean isOperator(String token) {
        return token.equals("+") || token.equals("-") || token.equals("*");
    }

    private int precedence(String operator) {
        return operator.equals("*") ? 2 : 1;
    }

    private static final class Poly {
        private final Map<String, Integer> coefficientByKey = new HashMap<>();

        static Poly constant(int value) {
            Poly poly = new Poly();
            if (value != 0) {
                poly.coefficientByKey.put("", value);
            }
            return poly;
        }

        static Poly variable(String variable) {
            Poly poly = new Poly();
            poly.coefficientByKey.put(variable, 1);
            return poly;
        }

        Poly plus(Poly other, int sign) {
            Poly result = new Poly();
            result.coefficientByKey.putAll(coefficientByKey);
            for (Map.Entry<String, Integer> entry : other.coefficientByKey.entrySet()) {
                int value = result.coefficientByKey.getOrDefault(entry.getKey(), 0) + sign * entry.getValue();
                if (value == 0) {
                    result.coefficientByKey.remove(entry.getKey());
                } else {
                    result.coefficientByKey.put(entry.getKey(), value);
                }
            }
            return result;
        }

        Poly times(Poly other) {
            Poly result = new Poly();
            for (Map.Entry<String, Integer> left : coefficientByKey.entrySet()) {
                for (Map.Entry<String, Integer> right : other.coefficientByKey.entrySet()) {
                    String key = mergeKeys(left.getKey(), right.getKey());
                    int value = result.coefficientByKey.getOrDefault(key, 0) + left.getValue() * right.getValue();
                    if (value == 0) {
                        result.coefficientByKey.remove(key);
                    } else {
                        result.coefficientByKey.put(key, value);
                    }
                }
            }
            return result;
        }

        private static String mergeKeys(String left, String right) {
            List<String> variables = new ArrayList<>();
            if (!left.isEmpty()) {
                variables.addAll(Arrays.asList(left.split("\\*")));
            }
            if (!right.isEmpty()) {
                variables.addAll(Arrays.asList(right.split("\\*")));
            }
            Collections.sort(variables);
            return String.join("*", variables);
        }

        List<String> toList() {
            List<String> keys = new ArrayList<>(coefficientByKey.keySet());
            keys.sort((a, b) -> {
                int degreeA = degree(a);
                int degreeB = degree(b);
                if (degreeA != degreeB) {
                    return degreeB - degreeA;
                }
                return a.compareTo(b);
            });

            List<String> result = new ArrayList<>();
            for (String key : keys) {
                int coefficient = coefficientByKey.get(key);
                if (coefficient == 0) {
                    continue;
                }
                result.add(key.isEmpty() ? String.valueOf(coefficient) : coefficient + "*" + key);
            }
            return result;
        }

        private int degree(String key) {
            return key.isEmpty() ? 0 : key.split("\\*").length;
        }
    }
}
